"""Запись в прод 20.10.2026 — БД.КОАКС: дозаполнение пропусков, «U.FL и MHF1 — разные серии», три аномалии.

Владелец 20.10: «проверь все данные и заполни всё, что есть, по возможности не оставляй пропуски»; «U.FL — это вообще чуть другое»
(U.FL — Hirose, MHF1 / IPEX — I-PEX; свои артикулы и данные). Исключены строки RUICHI (ими занят другой исполнитель).

Что делает (каждая ячейка — с защитой старого значения, тем же путём, что «Изменить» в «Базе данных»: `_edit_in` + `_same_article`,
т.е. свойства разъёма идут и в остальные строки артикула — «у одного артикула одни значения»; ключ строки — id прода + проверка
артикула и кабеля, не ID с чужой копии):
  1. ВОЗВРАТ строки «MHF1-plug RG-178» (её 20.10 по ошибке слили в «U.FL» и удалили; PR #606): те же поля из отката, своя серия MHF1
     (I-PEX); предложение поставщика gsm-repiteri.ru 3148 в неё НЕ возвращается — это страница товара «U.fl female (IPX)», она у
     строки «U.FL».
  2. «U.FL»: убирается то, что слияние записало в её строку («Производитель = I-PEX (аналог)» и пометка в «Источнике»).
  3. Аномалии: «SMA-Male flanged» (на странице kroks.ru — розетка SMA(female): тип, пол и название исправлены); «S-231F» (код
     kroks.ru 526 — это товар S-211F, у S-231F остаётся код gsm-repiteri.ru 3759). «BNC-C58P» (RUICHI) не трогается — см. отчёт.
  4. Дозаполнение по документам: свойства по типу (Серия, Пол, Исполнение, Полярность), по странице товара из «Ссылки» строки
     (Волновое сопротивление, Частота, КСВ, Тип пина, Тип экрана, код поставщика, название, производитель сайта изготовителя
     amel.ru), по серии (Волновое сопротивление там, где у всех заполненных строк серии одно значение), по строке-аналогу
     (HEX). Каждая строка получает пометку в «Источнике данных»: что и по чему дозаполнено.
Режимы:
  cd /opt/erp/app/deploy
  sudo -n docker compose --env-file /opt/erp/config/.env -f docker-compose.yml run --rm -T api python - dry   < этот файл
  sudo -n bash /opt/erp/app/deploy/erp.sh backup-now
  ... python - apply < этот файл      (в конце — CSV-журнал отката)
  ... python - dry   < этот файл      (→ всё «уже так»)
  ... -v $PWD/журнал.csv:/tmp/журнал.csv ... python - rollback /tmp/журнал.csv
"""
