def fold(value) -> str:
    return " ".join(str(value or "").casefold().split())


def article_of(record) -> str:
    return str(record.fields.get("coaxArticle") or record.fields.get("Артикул") or "").strip()


def cable_of(record) -> str:
    return str(record.fields.get("coaxWire") or record.fields.get("Провод") or "").strip()


def load(factory):
    with factory() as uow:
        return uow.tech_operations.list(tab=TechOperationTab.COAX, query="", limit=100_000)


def find_row(records, item):
    """Строка по id прода; артикул — старый или новый (переименование в этом же прогоне), кабель — тот же."""
    row = next((r for r in records if str(r.id) == item["id"]), None)
    if row is None or fold(cable_of(row)) != fold(item["cable"]):
        return None
    names = {fold(item["article"])} | {fold(e[2]) for e in item["edits"] if e[0] == "Артикул"}
    return row if fold(article_of(row)) in names else None


def plan_row(record, edits):
    """(к записи, уже так, отказ): ячейка уже равна новому — «уже так»; не равна ни старому, ни новому — отказ."""
    todo, done, refused = [], [], []
    for field, old, new in edits:
        have = str(record.fields.get(field, "") or "")
        if have == new:
            done.append((field, old, new))
        elif have != old:
            refused.append((field, old, new, have))
        else:
            todo.append((field, old, new))
    return todo, done, refused


def write_row(factory, probe, record_id, todo, now):
    for i in range(0, len(todo), MAX_ROW_EDITS):
        chunk = tuple(FieldEdit(f, o, n) for f, o, n in todo[i:i + MAX_ROW_EDITS])
        with (nullcontext(probe) if probe is not None else factory()) as uow:
            record, updated = _edit_in(record_id, chunk, now, uow)
            _same_article(updated, chunk, now, uow)
            if probe is None:
                _audit("references.tech_record_edited", ACTOR, now, {
                    "record_id": str(record.id), "tab": record.tab.value, "fields": [e.field for e in chunk],
                    "reason": REASON}, uow)
                uow.commit()


def create_rows(factory, now, dry, log):
    problems = 0
    for spec in CREATE:
        existing = [r for r in load(factory) if fold(article_of(r)) == fold(spec["fields"]["Артикул"])
                    and fold(cable_of(r)) == fold(spec["fields"]["Провод"])]
        head = f"«{spec['fields']['Артикул']}» × {spec['fields']['Провод']}"
        if existing:
            print(f"   уже есть: {head}")
            continue
        print(f"   {'будет создана' if dry else 'создаётся'}: {head}")
        report = import_rows("coax", factory(), [ImportRowIn(fields=spec["fields"], old={})], ACTOR, now, dry_run=dry,
                             source="erp").model_dump()
        if report["refused"] or (not dry and len(report["created"]) != 1) or (dry and len(report["created"]) != 1):
            problems += 1
            print("   ОТКАЗ создания:", report)
        elif not dry:
            for r in load(factory):
                if fold(article_of(r)) == fold(spec["fields"]["Артикул"]) and fold(cable_of(r)) == fold(spec["fields"]["Провод"]):
                    log.append(["создана", str(r.id), article_of(r), cable_of(r), "", "", ""])
    return problems


def main(mode: str) -> int:
    factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
    dry = mode == "dry"
    now = moscow_now()
    log: list[list[str]] = []
    problems = create_rows(factory, now, dry, log)
    records = load(factory)
    print(f"строк БД.КОАКС: {len(records)}; строк в плане: {len(PAYLOAD)}; создаётся: {len(CREATE)}")
    written, same_already = 0, 0
    probe_cm = factory() if dry else nullcontext(None)
    with probe_cm as probe:
        for item in PAYLOAD:
            current = probe.tech_operations.list(tab=TechOperationTab.COAX, query="", limit=100_000) if dry else load(factory)
            row = find_row(current, item)
            head = f"«{item['article']}» × {item['cable']}"
            if row is None:
                problems += 1
                print(f"   ОТКАЗ: строка не найдена (id/артикул/кабель не совпали) — {head}")
                continue
            todo, done, refused = plan_row(row, item["edits"])
            if refused:
                problems += 1
                for field, old, new, have in refused:
                    print(f"   ОТКАЗ: {head}: {field} — сейчас «{have[:80]}», ждали «{old[:80]}»")
                continue
            if not todo:
                same_already += 1
                continue
            print(f"   к записи: {head}: " + ", ".join(f for f, _, _ in todo if f != "Источник данных"))
            try:
                write_row(factory, probe, row.id, todo, now)
                written += len(todo)
            except (StaleRecordError, ReferenceValidationError, LookupError) as error:
                problems += 1
                print(f"   ОТКАЗ записи {head}: {error}")
    if not dry:
        after = {r.id: r for r in load(factory)}
        before = {r.id: r for r in records}
        log.insert(0, ["вид", "id", "артикул", "кабель", "поле", "было", "стало"])
        for rid, rec in after.items():
            was = before.get(rid)
            if was is None:
                continue
            for name in sorted(set(rec.fields) | set(was.fields)):
                if str(was.fields.get(name, "")) != str(rec.fields.get(name, "")) and not is_coax_cable_column(name) \
                        and name not in schema_keys("coax"):
                    log.append(["ячейка", str(rid), article_of(was), cable_of(was), name, str(was.fields.get(name, "")),
                                str(rec.fields.get(name, ""))])
        print("\n== CSV-журнал отката ==")
        buffer = io.StringIO()
        csv.writer(buffer, lineterminator="\n").writerows(log)
        print(buffer.getvalue())
    summary = {"строк": len(PAYLOAD), "ячеек к записи/записано": written, "уже так": same_already, "проблем": problems}
    print("ИТОГО", json.dumps(summary, ensure_ascii=False), "(проверка, ничего не записано)" if dry else "(записано)")
    return 1 if problems else 0


def rollback(path: str) -> int:
    factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
    now = moscow_now()
    problems = 0
    with open(path, encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle))
    for row in reversed(rows):
        with factory() as uow:
            try:
                if row["вид"] == "создана":
                    record = uow.tech_operations.get(UUID(row["id"]))
                    uow.tech_operations.delete(record.id)
                    _audit("references.record_deleted", ACTOR, now, {
                        "record_id": str(record.id), "tab": record.tab.value, "display_text": record.display_text,
                        "sort_key": record.sort_key, "source_sheet": record.source_sheet, "mirror_key": record.mirror_key,
                        "edited_in_erp": record.edited_in_erp, "fields": dict(record.fields),
                        "reason": "откат дозаполнения БД.КОАКС 20.10.2026"}, uow)
                    uow.commit()
                    print(f"   откат: удалена созданная строка {row['артикул']} × {row['кабель']}")
                    continue
                record, _ = _edit_in(UUID(row["id"]), (FieldEdit(row["поле"], row["стало"], row["было"]),), now, uow)
                _audit("references.tech_record_edited", ACTOR, now, {
                    "record_id": str(record.id), "tab": record.tab.value, "fields": [row["поле"]],
                    "reason": "откат дозаполнения БД.КОАКС 20.10.2026"}, uow)
                uow.commit()
                print(f"   откат {row['артикул']} × {row['кабель']}: {row['поле']}")
            except (StaleRecordError, ReferenceValidationError, LookupError) as error:
                problems += 1
                print(f"   отказ: {row['артикул']} {row['поле']}: {error}")
    print("ИТОГО откат, проблем:", problems)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8")
    run_mode = (sys.argv[1] if len(sys.argv) > 1 else "dry").strip()
    if run_mode not in ("dry", "apply", "rollback"):
        raise SystemExit("режим: dry | apply | rollback <csv>")
    raise SystemExit(rollback(sys.argv[2]) if run_mode == "rollback" else main(run_mode))
